class DefaultArticlesData {
  static final List<Map<String, dynamic>> defaultArticles = [
    {"id": "article_computer_inside", "title": "الكمبيوتر من الداخل: إيه اللي جوه الجهاز؟ دليل مبسط لفهم مكونات الكمبيوتر", "category": "علوم الحاسب والبرمجة", "htmlCode": "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>الكمبيوتر من الداخل: إيه اللي جوه الجهاز؟ دليل مبسط لفهم مكونات الكمبيوتر | برمجة في دقيقة</title>\n  \n  <meta name=\"description\" content=\"دليل مبسط وممتع يشرح ما بداخل الكمبيوتر: المعالج CPU، ذاكرة الرام RAM، وحدات التخزين SSD و HDD، اللوحة الأم، كارت الشاشة GPU، والتبريد، مع صور واختبار تفاعلي.\">\n  <meta name=\"keywords\" content=\"مكونات الكمبيوتر, ما هو المعالج, الفرق بين الرام والروم, كارت الشاشة, الهاردوير والسوفتوير, برمجة في دقيقة, إسلام عاطف, STEM\">\n  <meta name=\"author\" content=\"م. إسلام عاطف | Eslam Atef\">\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    :root {\n      --primary: #0284c7;\n      --primary-dark: #0369a1;\n      --primary-light: #f0f9ff;\n      --secondary: #0f172a;\n      --accent: #f59e0b;\n      --accent-light: #fef3c7;\n      --success: #10b981;\n      --success-light: #ecfdf5;\n      --danger: #ef4444;\n      --purple: #8b5cf6;\n      --purple-light: #f5f3ff;\n      --text: #0f172a;\n      --text-muted: #475569;\n      --bg: #f8fafc;\n      --surface: #ffffff;\n      --border: #e2e8f0;\n      --radius: 16px;\n      --shadow: 0 10px 30px -5px rgba(15, 23, 42, 0.07);\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Cairo', sans-serif; }\n    body { background: var(--bg); color: var(--text); line-height: 1.85; padding: 24px 16px; }\n    .container { max-width: 920px; margin: 0 auto; }\n\n    /* Header & Hero */\n    .article-header {\n      background: linear-gradient(135deg, #091e42 0%, #0369a1 60%, #0284c7 100%);\n      color: #ffffff;\n      border-radius: var(--radius);\n      padding: 42px 32px;\n      margin-bottom: 28px;\n      box-shadow: 0 15px 35px -5px rgba(2, 132, 199, 0.28);\n      position: relative;\n      overflow: hidden;\n    }\n    .article-header::after {\n      content: '🖥️';\n      position: absolute;\n      left: 20px;\n      bottom: -15px;\n      font-size: 130px;\n      opacity: 0.12;\n      pointer-events: none;\n    }\n    .badge-series {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(255, 255, 255, 0.18);\n      backdrop-filter: blur(10px);\n      padding: 6px 18px;\n      border-radius: 50px;\n      font-size: 13.5px;\n      font-weight: 800;\n      margin-bottom: 16px;\n      border: 1px solid rgba(255, 255, 255, 0.25);\n    }\n    .article-header h1 {\n      font-size: clamp(23px, 3.2vw, 36px);\n      font-weight: 900;\n      line-height: 1.35;\n      margin-bottom: 14px;\n    }\n    .article-header p {\n      font-size: 17px;\n      opacity: 0.95;\n      max-width: 760px;\n      line-height: 1.7;\n    }\n    .article-meta {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 16px;\n      margin-top: 20px;\n      font-size: 13.5px;\n      color: rgba(255, 255, 255, 0.85);\n      font-weight: 600;\n    }\n\n    /* Content Cards */\n    .content-card {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 32px 28px;\n      margin-bottom: 26px;\n      box-shadow: var(--shadow);\n    }\n    .content-card h2 {\n      font-size: clamp(20px, 2.2vw, 26px);\n      font-weight: 900;\n      color: var(--text);\n      margin-bottom: 18px;\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      border-bottom: 2px solid #f1f5f9;\n      padding-bottom: 12px;\n    }\n    .content-card h3 {\n      font-size: 19px;\n      font-weight: 800;\n      color: var(--primary-dark);\n      margin: 22px 0 10px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .content-card p {\n      font-size: 16.5px;\n      color: var(--text-muted);\n      margin-bottom: 16px;\n      line-height: 1.85;\n    }\n    .content-card strong { color: var(--text); }\n\n    /* Images with Elegant Captions */\n    .article-image-box {\n      margin: 26px 0;\n      border-radius: 14px;\n      overflow: hidden;\n      border: 1.5px solid var(--border);\n      background: #0f172a;\n      box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08);\n      text-align: center;\n    }\n    .article-image-box img {\n      width: 100%;\n      height: auto;\n      display: block;\n      transition: transform 0.3s ease;\n    }\n    .article-image-box:hover img {\n      transform: scale(1.01);\n    }\n    .img-caption {\n      padding: 12px 18px;\n      background: #ffffff;\n      color: #475569;\n      font-size: 14px;\n      font-weight: 700;\n      border-top: 1px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n    }\n\n    /* Callout Alert Boxes */\n    .callout {\n      border-right: 5px solid var(--primary);\n      background: var(--primary-light);\n      padding: 18px 22px;\n      border-radius: 10px;\n      margin: 20px 0;\n      font-size: 15.5px;\n      color: #0369a1;\n      line-height: 1.8;\n    }\n    .callout.accent {\n      border-color: var(--accent);\n      background: var(--accent-light);\n      color: #92400e;\n    }\n    .callout.purple {\n      border-color: var(--purple);\n      background: var(--purple-light);\n      color: #6b21a8;\n    }\n    .callout.success {\n      border-color: var(--success);\n      background: var(--success-light);\n      color: #065f46;\n    }\n\n    /* Comparison Grid */\n    .duo-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n      gap: 18px;\n      margin: 22px 0;\n    }\n    .duo-card {\n      background: #f8fafc;\n      border: 1.5px solid var(--border);\n      border-radius: 14px;\n      padding: 22px;\n      transition: transform 0.2s ease, border-color 0.2s ease;\n    }\n    .duo-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--primary);\n    }\n    .duo-card.hardware { border-top: 5px solid #0284c7; }\n    .duo-card.software { border-top: 5px solid #8b5cf6; }\n    .duo-card h4 {\n      font-size: 18px;\n      font-weight: 800;\n      margin-bottom: 10px;\n      color: var(--text);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .duo-card p {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 8px;\n    }\n\n    /* Component Feature Cards Grid */\n    .components-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n      gap: 16px;\n      margin: 22px 0;\n    }\n    .component-badge-card {\n      background: #ffffff;\n      border: 1.5px solid var(--border);\n      border-radius: 12px;\n      padding: 18px;\n      box-shadow: 0 4px 10px rgba(0,0,0,0.02);\n    }\n    .component-badge-card h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .component-badge-card p {\n      font-size: 14px;\n      color: var(--text-muted);\n      line-height: 1.6;\n      margin: 0;\n    }\n\n    /* Step-by-Step Flow */\n    .steps-container {\n      margin: 24px 0;\n    }\n    .step-item {\n      display: flex;\n      gap: 16px;\n      margin-bottom: 18px;\n      align-items: flex-start;\n    }\n    .step-number {\n      background: var(--primary);\n      color: #fff;\n      font-weight: 900;\n      font-size: 15px;\n      width: 34px;\n      height: 34px;\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-shrink: 0;\n      box-shadow: 0 4px 10px rgba(2, 132, 199, 0.3);\n    }\n    .step-text {\n      background: #f8fafc;\n      border: 1px solid var(--border);\n      border-radius: 12px;\n      padding: 14px 18px;\n      flex-grow: 1;\n      font-size: 15.5px;\n      color: var(--text-muted);\n    }\n    .step-text strong { color: var(--text); }\n\n    /* Interactive Comparison Table */\n    .table-container {\n      overflow-x: auto;\n      margin: 22px 0;\n      border-radius: 12px;\n      border: 1.5px solid var(--border);\n    }\n    table { width: 100%; border-collapse: collapse; text-align: right; background: #fff; }\n    th, td { padding: 14px 18px; font-size: 15px; border-bottom: 1px solid var(--border); }\n    th { background: #f1f5f9; font-weight: 800; color: var(--text); }\n    tr:last-child td { border-bottom: none; }\n    tr:hover td { background: #f8fafc; }\n\n    /* Interactive Quiz Section */\n    .quiz-container {\n      background: linear-gradient(180deg, #ffffff 0%, #f0fdf4 100%);\n      border: 2px solid #86efac;\n      border-radius: var(--radius);\n      padding: 34px 28px;\n      margin-bottom: 30px;\n      box-shadow: 0 12px 30px -5px rgba(16, 185, 129, 0.12);\n    }\n    .quiz-title {\n      font-size: 24px;\n      font-weight: 900;\n      color: #14532d;\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n    .quiz-desc {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 24px;\n    }\n    .quiz-q {\n      background: #ffffff;\n      border: 1.5px solid #cbd5e1;\n      border-radius: 12px;\n      padding: 20px;\n      margin-bottom: 18px;\n    }\n    .quiz-q-title {\n      font-size: 16.5px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 14px;\n    }\n    .quiz-options {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .opt-btn {\n      padding: 12px 16px;\n      border: 1.5px solid #e2e8f0;\n      background: #f8fafc;\n      border-radius: 10px;\n      cursor: pointer;\n      font-size: 14.5px;\n      font-weight: 600;\n      text-align: right;\n      transition: all 0.2s ease;\n      color: #334155;\n    }\n    .opt-btn:hover {\n      background: #eff6ff;\n      border-color: #38bdf8;\n      color: #0284c7;\n    }\n    .opt-btn.correct {\n      background: #dcfce7 !important;\n      border-color: #22c55e !important;\n      color: #15803d !important;\n      font-weight: 800;\n    }\n    .opt-btn.wrong {\n      background: #fee2e2 !important;\n      border-color: #ef4444 !important;\n      color: #b91c1c !important;\n    }\n    .quiz-feedback {\n      margin-top: 10px;\n      font-size: 14px;\n      font-weight: 700;\n      display: none;\n      padding: 8px 12px;\n      border-radius: 6px;\n    }\n\n    /* Interactive Discussion Question */\n    .interactive-question {\n      background: linear-gradient(135deg, #fef3c7 0%, #fffbeb 100%);\n      border: 2px dashed #f59e0b;\n      border-radius: var(--radius);\n      padding: 28px 24px;\n      margin-bottom: 28px;\n      text-align: center;\n    }\n    .interactive-question h3 {\n      font-size: 21px;\n      font-weight: 900;\n      color: #92400e;\n      margin-bottom: 10px;\n    }\n    .interactive-question p {\n      font-size: 16px;\n      color: #78350f;\n      max-width: 650px;\n      margin: 0 auto 16px;\n      line-height: 1.7;\n    }\n\n    /* Footer & Signature */\n    .article-footer {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 28px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 18px;\n    }\n    .author-info {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n    }\n    .author-avatar {\n      width: 52px;\n      height: 52px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #0284c7, #0f172a);\n      color: #fff;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      font-weight: 900;\n      box-shadow: 0 4px 12px rgba(2, 132, 199, 0.3);\n    }\n    .author-details h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n    }\n    .author-details p {\n      font-size: 13.5px;\n      color: var(--text-muted);\n      margin: 0;\n    }\n\n    @media (max-width: 650px) {\n      .article-header { padding: 28px 20px; }\n      .content-card { padding: 22px 18px; }\n      .article-footer { flex-direction: column; text-align: center; }\n      .author-info { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n\n<div class=\"container\">\n\n  <!-- ==========================================\n       1. HERO HEADER\n       ========================================== -->\n  <header class=\"article-header\">\n    <div class=\"badge-series\">\n      <span>💡 معلومة تكنولوجية كل جمعة</span>\n      <span>•</span>\n      <span>برمجة في دقيقة</span>\n    </div>\n    <h1>الكمبيوتر من الداخل: إيه اللي جوه الجهاز؟ دليل مبسط لفهم مكونات الكمبيوتر</h1>\n    <p>لما بنستخدم الكمبيوتر في الدراسة أو الشغل أو اللعب، بنشوف الشاشة والكيبورد والماوس، لكن معظم العمليات المهمة بتحصل داخل الجهاز نفسه. تعالوا نكتشف أسرار المكونات الإلكترونية التي تعمل معاً في تناغم فائق!</p>\n    <div class=\"article-meta\">\n      <span>✍️ بقلم: م. إسلام عاطف (Eslam Atef)</span>\n      <span>⏱️ وقت القراءة: 5 دقائق</span>\n      <span>🎯 المستوى: دليل شامل للمبتدئين واليافعين والمهتمين بالتقنية</span>\n    </div>\n  </header>\n\n  <!-- ==========================================\n       IMAGE 1: MAIN SHOWCASE (الصورة الأولى)\n       ========================================== -->\n  <div class=\"article-image-box\">\n    <img src=\"https://k.top4top.io/p_3951cly8o1.png\" alt=\"الكمبيوتر من الداخل إيه اللي جوه الجهاز؟ دليل مبسط لفهم مكونات الكمبيوتر\">\n    <div class=\"img-caption\">\n      <span>🔍</span>\n      <span>نظرة فاحصة داخل صندوق الكمبيوتر: كيف تتعاون الأجزاء الإلكترونية سوياً لتقديم أداء فائق وسلس؟</span>\n    </div>\n  </div>\n\n  <!-- ==========================================\n       2. INTRODUCTION & HARDWARE VS SOFTWARE\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🎯 ما هي مكونات الكمبيوتر الحقيقية؟</h2>\n    <p>عند الضغط على زر التشغيل، يبدأ عالم مذهل من الإشارات الكهربائية ونبضات البيانات بالعمل في أجزاء من الألف من الثانية. لفهم هذا العالم، يمكن تقسيم مكونات أي نظام كمبيوتر في العالم إلى نوعين رئيسيين:</p>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card hardware\">\n        <h4>🔌 أولاً: المكونات المادية (Hardware)</h4>\n        <p>هي كل الأجزاء الإلكترونية والميكانيكية الملموسة اللي تقدر تشوفها بعينك أو تلمسها بإيدك، زي المعالج، والرام، واللوحة الأم، ووحدة التخزين، والشاشة، والكيبورد.</p>\n      </div>\n      <div class=\"duo-card software\">\n        <h4>💻 ثانياً: البرمجيات (Software)</h4>\n        <p>هي الأوامر والتعليمات والأكواد البرمجية اللي بتوجّه الهاردوير للقيام بوظائفه، زي نظام التشغيل (Windows أو macOS)، ومتصفح الويب، والألعاب، وتطبيقات التصميم.</p>\n      </div>\n    </div>\n\n    <div class=\"callout\">\n      💡 <strong>التكامل الذهبي:</strong> الجهاز يحتاج المكونات المادية والبرمجيات معاً كروح وجسد؛ فلا فائدة من أقوى معالج في العالم دون سوفتوير يوجهه، ولا يمكن لبرنامج أن يعمل في الهواء دون هاردوير ينفذ أوامره!\n    </div>\n  </section>\n\n  <!-- ==========================================\n       3. DEEP DIVE: THE 7 CORE HARDWARE PARTS\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🧩 جولة داخل صندوق الكمبيوتر: الأجزاء السبعة الرئيسية</h2>\n    <p>دعونا نفتح غطاء الجهاز ونستكشف وظيفة كل قطعة حيوية بأسلوب مبسط وعلمي دقيق:</p>\n\n    <!-- Component 1 -->\n    <h3>1. المعالج CPU: العقل المفكر والمسؤول عن تنفيذ التعليمات</h3>\n    <p>المعالج أو <strong>Central Processing Unit</strong> هو أهم مكوّن في الكمبيوتر على الإطلاق. وظيفته تنفيذ تعليمات البرامج، وإجراء العمليات الحسابية والمنطقية، وتنظيم خطوات تنفيذ المهام بين مختلف القطع.</p>\n    <p>لما تفتح برنامجاً أو تضغط على أمر داخل لعبة، المعالج هو اللي بيفكك هذا الأمر وينفّذه بالمليارات في الثانية الواحدة. والمعالج ليس مجرد آلة حاسبة بسيطة؛ هو وحدة حوسبة عامة شديدة التعقيد تعتمد كفاءتها على عدد الأنوية (Cores) وسرعة التردد (Clock Speed).</p>\n\n    <!-- Component 2 -->\n    <h3>2. ذاكرة RAM: مساحة العمل المؤقتة وسرعة الاستجابة</h3>\n    <p>كلمة <strong>RAM</strong> هي اختصار لـ <em>Random Access Memory</em> (ذاكرة الوصول العشوائي)، وهي الذاكرة الفائقة السرعة اللي بيستخدمها الكمبيوتر للاحتفاظ المؤقت بالبيانات والتعليمات اللي محتاجها حالياً أثناء التشغيل.</p>\n    \n    <div class=\"callout accent\">\n      📚 <strong>تشبيه عملي لطيف:</strong> تخيّل إنك بتذاكر في غرفتك وعندك مكتب تضع عليه الكتب والأوراق اللي شغال فيها دلوقتي حالا. كل ما كانت مساحة المكتب أوسع، تقدر تفتح مراجع أكتر وتشتغل براحتك وبسرعة دون ما تضطر تقفل كتاب عشان تفتح غيره!\n    </div>\n    <p>الرام بتؤدي نفس الدور تماماً؛ وكل ما زادت، قدرت تفتح برامج وتطبيقات كتير في نفس الوقت دون تهنيج. وتذكّر دائماً أن الرام <strong>ذاكرة متطايرة</strong>، أي تفقد كل محتوياتها فور انقطاع الكهرباء أو إغلاق الجهاز.</p>\n\n    <!-- ==========================================\n         IMAGE 2: HARDWARE INTEGRATION (الصورة الثانية)\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://l.top4top.io/p_3951znq7u2.png\" alt=\"المعالجات واللوحة الأم وكروت الشاشة والذواكر داخل الكمبيوتر\">\n      <div class=\"img-caption\">\n        <span>⚡</span>\n        <span>المكونات الدقيقة المتصلة باللوحة الأم: تناغم رقمي بين المعالج المركزي وشرائح الرام ووحدات المعالجة الرسومية</span>\n      </div>\n    </div>\n\n    <!-- Component 3 -->\n    <h3>3. وحدة التخزين SSD أو HDD: المكان اللي بنحفظ فيه ملفاتنا للأبد</h3>\n    <p>الكمبيوتر محتاج خزانة دائمة تحتفظ بالملفات والبرامج حتى بعد إيقاف تشغيل الجهاز وفصل التيار، وهنا يأتي دور وحدة التخزين الدائمة. وأشهر نوعين هما:</p>\n    \n    <div class=\"duo-grid\">\n      <div class=\"duo-card\">\n        <h4>⚡ أقراص الحالة الصلبة (SSD)</h4>\n        <p>وحدة تخزين إلكترونية بالكامل سريعة جداً؛ لا تحتوي على أجزاء متحركة، وبتساعد في إقلاع الويندوز في ثوانٍ وفتح البرامج الثقيلة بلمح البصر.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>💿 الأقراص الميكانيكية (HDD)</h4>\n        <p>قرص تخزين مغناطيسي ميكانيكي يدور بداخله قرص معدني، يوفر مساحات تخزين ضخمة بتكلفة اقتصادية، وهو مثالي لأرشفة الملفات والفيديوهات الكبيرة.</p>\n      </div>\n    </div>\n\n    <!-- Component 4 -->\n    <h3>4. اللوحة الأم Motherboard: شبكة الطرق وحلقة الوصل الكبرى</h3>\n    <p>اللوحة الأم هي اللوحة الإلكترونية الرئيسية الكبرى اللي بتتصل بيها كل أجزاء الكمبيوتر بلا استثناء. تخيّلها كأنها <strong>شبكة الطرق السريعة ومحطات القطار</strong> اللي بتربط أحياء مدينة كبرى ببعضها.</p>\n    <p>من خلال مساراتها النحاسية الدقيقة، يتبادل المعالج والرام وكارت الشاشة والتخزين البيانات بسرعات خيالية، وبدونها لا يمكن لهذه القطع المنفصلة أن تتواصل أو تتعاون معاً إطلاقاً.</p>\n\n    <!-- Component 5 -->\n    <h3>5. كارت الشاشة GPU: بطل الرسومات والألعاب والذكاء الاصطناعي</h3>\n    <p>الـ <strong>GPU</strong> اختصار لـ <em>Graphics Processing Unit</em>، وهو المسؤول المتخصص عن معالجة وعرض كل بكسل تراه على شاشتك: من جرافيك ألعاب ثلاثية الأبعاد، والمؤثرات البصرية، إلى المونتاج وتحرير الفيديو بدقة 4K.</p>\n    <p>ومع الطفرة التكنولوجية الحديثة، أصبحت وحدات معالجة الرسومات القوة الضاربة التي تدرب نماذج <strong>الذكاء الاصطناعي (AI)</strong> بفضل قدرتها الفريدة على إجراء آلاف الحسابات الرياضية في وقت واحد (Parallel Processing).</p>\n\n    <!-- Component 6 -->\n    <h3>6. مزوّد الطاقة Power Supply: قلب الجهاز النابض بالكهرباء</h3>\n    <p>مزوّد الطاقة (PSU) هو الحارس المسؤول عن استلام التيار المتردد العالي من مقبس الحائط وتحويله بأمان فائق إلى تيارات مستمرة وجهود منخفضة دقيقة (زي 12V و 5V و 3.3V) تحتاجها كل قطعة إلكترونية حساسة في جهازك.</p>\n\n    <!-- Component 7 -->\n    <h3>7. نظام التبريد Cooling: الحماية من الحرارة الزائدة</h3>\n    <p>العمليات الحسابية المليارية التي يُجريها المعالج وكارت الشاشة ينتج عنها طاقة حرارية هائلة. لذلك تعتمد الأجهزة على مراوح ومشتتات نحاسية أو أنظمة تبريد مائي مغلقة لمنع ارتفاع درجات الحرارة وحماية الأجهزة من اختناق الأداء (Thermal Throttling).</p>\n  </section>\n\n  <!-- ==========================================\n       4. HOW IT ALL WORKS TOGETHER (SCENARIO)\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🎬 إزاي مكونات الكمبيوتر بتشتغل مع بعض في اللحظة نفسها؟</h2>\n    <p>خلونا نتخيل سيناريو واقعي بسيط جداً: <strong>أنت فتحت برنامجاً لتعديل الصور أو شغلت لعبة مفضلة.. إيه اللي بيحصل في الكواليس؟</strong></p>\n\n    <div class=\"steps-container\">\n      <div class=\"step-item\">\n        <div class=\"step-number\">1</div>\n        <div class=\"step-text\">\n          <strong>الطلب والتحميل:</strong> بمجرد ما تضغط دبل كليك، نظام التشغيل يطلب ملفات البرنامج من وحدة التخزين الدائمة (SSD) وينقلها فوراً إلى الذاكرة السريعة (RAM).\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">2</div>\n        <div class=\"step-text\">\n          <strong>التنفيذ الحسابي:</strong> المعالج المركزي (CPU) يبدأ يقرأ كود البرنامج من الرام وينفّذ تعليمات التشغيل ويستجيب لضغطاتك على الماوس والكيبورد.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">3</div>\n        <div class=\"step-text\">\n          <strong>المعالجة الرسومية:</strong> كارت الشاشة (GPU) يستلم بيانات المشهد والألوان من المعالج ويحوّلها فوراً إلى إطارات وصور مبهرة معروضة على شاشتك.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">4</div>\n        <div class=\"step-text\">\n          <strong>التبريد وتغذية الطاقة:</strong> مزوّد الطاقة يضخ التيارات المطلوبة، بينما تعمل المراوح على تصريف الحرارة المتولدة فورياً.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">5</div>\n        <div class=\"step-text\">\n          <strong>الحفظ النهائي:</strong> لما تدوس \"Save\"، المعالج يوجّه بكتابة الصورة المعدلة بشكل نهائي داخل الـ SSD لتظل محفوظة حتى بعد إغلاق الجهاز!\n        </div>\n      </div>\n    </div>\n\n    <!-- ==========================================\n         IMAGE 3: SYSTEM FLOW & ARCHITECTURE (الصورة الثالثة)\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://a.top4top.io/p_3951x9trj3.png\" alt=\"مخطط تدفق العمل بين المعالج والذاكرة والتخزين وكارت الشاشة\">\n      <div class=\"img-caption\">\n        <span>🔄</span>\n        <span>منظومة العمل المتكاملة: كيف تتكامل كل قطعة في توقيت محسوب بالنانو ثانية لإنجاز مهامك اليومية؟</span>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       5. BOTTLENECK ANALYSIS: هل الرام وحدها تكفي؟\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🤔 هل زيادة الرام وحدها بتخلي الكمبيوتر أسرع كالسحر؟</h2>\n    <p>الإجابة المختصرة: <strong>مش بالضرورة!</strong></p>\n    <p>لو جهازك كان بيعاني من امتلاء الرام بسبب فتح برامج كتيرة أو تابات متصفح متراكمة، فزيادة الرام هتفرق معاك جداً وهتنهي التهنيج. لكن لو المعالج نفسه قديم وبطيء، أو وحدة التخزين HDD بطيئة وعليها ضغط 100%، فزيادة الرام مش هتحل المشكلة إطلاقاً!</p>\n    \n    <div class=\"callout purple\">\n      ⚠️ <strong>مفهوم عنق الزجاجة (Bottleneck):</strong> الكمبيوتر يعمل دائماً بسرعة أبطأ مكوّن فيه! لذا فإن التطوير الأذكى يبدأ بتشخيص الجزء الأضعف أولاً (معالج، كارت شاشة، رام، أو تبديل الهارد بـ SSD سريع).\n    </div>\n\n    <!-- Summary Table -->\n    <div class=\"table-container\">\n      <table>\n        <thead>\n          <tr>\n            <th>المكوّن</th>\n            <th>الوظيفة الأساسية</th>\n            <th>نوع الذاكرة / الأداء</th>\n            <th>تأثير التطوير على الجهاز</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>المعالج (CPU)</strong></td>\n            <td>تنفيذ التعليمات والعمليات الحسابية</td>\n            <td>دائم العمل بالتردد والأنوية</td>\n            <td>تسريع كل المهام المعقدة والبرمجة</td>\n          </tr>\n          <tr>\n            <td><strong>الذاكرة (RAM)</strong></td>\n            <td>حفظ بيانات البرامج النشطة حالياً</td>\n            <td>مؤقتة وفائقة السرعة</td>\n            <td>فتح برامج أكثر وتصفح دون تهنيج</td>\n          </tr>\n          <tr>\n            <td><strong>التخزين (SSD)</strong></td>\n            <td>حفظ الويندوز والملفات للأبد</td>\n            <td>تخزين دائم لا يفقد بالكهرباء</td>\n            <td>إقلاع الويندوز وفتح البرامج في ثوانٍ</td>\n          </tr>\n          <tr>\n            <td><strong>كارت الشاشة (GPU)</strong></td>\n            <td>معالجة الصور والرسوميات والفيديو</td>\n            <td>معالجة متوازية متخصصة</td>\n            <td>سلاسة الألعاب العالية والرندر والـ AI</td>\n          </tr>\n          <tr>\n            <td><strong>اللوحة الأم (Motherboard)</strong></td>\n            <td>ربط كل المكونات ببعضها وتمرير الطاقة</td>\n            <td>منظومة التوصيل والتحكم</td>\n            <td>دعم ترقية أحدث المعالجات والسرعات</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       6. EMBEDDED INTERACTIVE QUIZ (اختبار تفاعلي)\n       ========================================== -->\n  <section class=\"quiz-container\">\n    <div class=\"quiz-title\">\n      <span>🧠</span>\n      <span>اختبر معلوماتك: كم تفهم من مكونات الكمبيوتر؟</span>\n    </div>\n    <p class=\"quiz-desc\">أجب عن الأسئلة التالية بضغطة واحدة واكتشف نتيجتك التفاعلية فورياً:</p>\n\n    <!-- Q1 -->\n    <div class=\"quiz-q\" id=\"q1\">\n      <div class=\"quiz-q-title\">1. ما هو المكون الذي يُعتبر «العقل المفكر» للكمبيوتر والمسؤول عن تنفيذ تعليمات البرامج؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, false, 'الرام ذاكرة مؤقتة وليست العقل المنفذ للأوامر.')\">ذاكرة الرام (RAM)</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, true, 'إجابة صحيحة وممتازة! المعالج CPU هو المسؤول الأول عن تنفيذ كل التعليمات والعمليات الحسابية.')\">المعالج المركزي (CPU)</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, false, 'مزوّد الطاقة يوفر الكهرباء فقط ولا يعالج البيانات.')\">مزوّد الطاقة (Power Supply)</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q1-fb\"></div>\n    </div>\n\n    <!-- Q2 -->\n    <div class=\"quiz-q\" id=\"q2\">\n      <div class=\"quiz-q-title\">2. ما الفرق الجوهري بين ذاكرة الرام (RAM) ووحدة التخزين (SSD / HDD)؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, true, 'رائع جداً! الرام تفقد بياناتها فور انقطاع الكهرباء وتستخدم أثناء التشغيل، بينما وحدة التخزين تحفظ الملفات دائماً.')\">الرام ذاكرة مؤقتة للعمل الحالي، ووحدة التخزين تحفظ الملفات للأبد بعد إغلاق الجهاز</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, false, 'غير صحيح، الرام أسرع بكثير من وحدة التخزين ولكنها متطايرة.')\">الرام أبطأ من وحدة التخزين</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, false, 'الرام مخصصة للملفات المؤقتة وليست لحفظ الألعاب للأبد.')\">الرام تحفظ الويندوز والملفات حتى بعد إيقاف الجهاز</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q2-fb\"></div>\n    </div>\n\n    <!-- Q3 -->\n    <div class=\"quiz-q\" id=\"q3\">\n      <div class=\"quiz-q-title\">3. لماذا يُعتبر كارت الشاشة (GPU) مهماً جداً في مجالات الذكاء الاصطناعي (AI) الحديثة؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, false, 'كارت الشاشة مسؤول عن الحسابات الرسومية والمتوازية وليس الطاقة.')\">لأنه يوفر كهرباء أكثر للجهاز</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, true, 'صحيح 100%! الـ GPU يحتوي على آلاف الأنوية الصغيرة القادرة على إجراء آلاف العمليات الحسابية في اللحظة نفسها.')\">لقدرته الفائقة على المعالجة المتوازية وتنفيذ مليارات الحسابات بالتزامن</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, false, 'اللوحة الأم هي التي تربط المكونات وليس كارت الشاشة.')\">لأنه يربط أجزاء الكمبيوتر ببعضها</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q3-fb\"></div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       7. INTERACTIVE DISCUSSION QUESTION\n       ========================================== -->\n  <div class=\"interactive-question\">\n    <h3>💬 سؤال تفاعلي للنقاش</h3>\n    <p>لو عندك كمبيوتر بطيء وعايز تطوره بميزانية محدودة.. إيه أول قطعة هتفكر تستبدلها أو تزودها: <strong>تركيب SSD سريع</strong>، ولا <strong>زيادة الرام RAM</strong>، ولا <strong>تطوير المعالج CPU</strong>؟</p>\n    <div class=\"callout success\" style=\"margin: 0 auto; max-width: 600px;\">\n      💡 <strong>نصيحة المهندس:</strong> في أغلب الأجهزة القديمة، الترقية السحرية ذات الأثر الفوري بأقل تكلفة هي استبدال قرص الـ HDD القديم بقرص <strong>SSD</strong> حديث!\n    </div>\n  </div>\n\n  <!-- ==========================================\n       8. ARTICLE FOOTER & SIGNATURE\n       ========================================== -->\n  <footer class=\"article-footer\">\n    <div class=\"author-info\">\n      <div class=\"author-avatar\">إ</div>\n      <div class=\"author-details\">\n        <h4>م. إسلام عاطف | Eslam Atef</h4>\n        <p>مهندس برمجيات ومدرب معتمد في البرمجة والذكاء الاصطناعي للأطفال والشباب</p>\n      </div>\n    </div>\n    <div style=\"font-size: 13.5px; color: #64748b; font-weight: 700;\">\n      🚀 برمجة في دقيقة — افهم التكنولوجيا ببساطة واكتشف كل أسبوع سراً جديداً خلف الشاشة.\n    </div>\n  </footer>\n\n</div>\n\n<script>\n  function checkAnswer(qId, btn, isCorrect, explanation) {\n    const parent = document.getElementById(qId);\n    const buttons = parent.querySelectorAll('.opt-btn');\n    const fb = document.getElementById(qId + '-fb');\n\n    buttons.forEach(b => {\n      b.disabled = true;\n      b.style.cursor = 'default';\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      fb.style.display = 'block';\n      fb.style.background = '#dcfce7';\n      fb.style.color = '#15803d';\n      fb.innerHTML = '✅ ' + explanation;\n    } else {\n      btn.classList.add('wrong');\n      fb.style.display = 'block';\n      fb.style.background = '#fee2e2';\n      fb.style.color = '#b91c1c';\n      fb.innerHTML = '❌ ' + explanation;\n    }\n  }\n</script>\n\n</body>\n</html>\n", "status": "منشور", "isPublished": true, "imageUrl": "https://k.top4top.io/p_3951cly8o1.png", "image": "https://k.top4top.io/p_3951cly8o1.png", "createdAt": "2026-10-25T12:00:00Z", "views": 140, "likes": 52},
    {"id": "article_hardware_vs_software", "title": "الفرق بين Hardware وSoftware: إيه الفرق بين الجهاز والبرامج؟", "category": "علوم الحاسب والبرمجة", "htmlCode": "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>الفرق بين Hardware وSoftware: إيه الفرق بين الجهاز والبرامج؟ | برمجة في دقيقة</title>\n  \n  <meta name=\"description\" content=\"دليل مبسط وشامل لفهم الفرق الجوهري بين المكونات المادية Hardware والبرمجيات Software، مع أمثلة عملية من حياتنا اليومية وشرح مفهوم Firmware واختبار تفاعلي.\">\n  <meta name=\"keywords\" content=\"الفرق بين hardware و software, ما هو الهاردوير, ما هو السوفتوير, ما هو الفيرموير Firmware, برمجة في دقيقة, إسلام عاطف, تعليم البرمجة للأطفال\">\n  <meta name=\"author\" content=\"م. إسلام عاطف | Eslam Atef\">\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    :root {\n      --primary: #0284c7;\n      --primary-dark: #0369a1;\n      --primary-light: #f0f9ff;\n      --secondary: #0f172a;\n      --accent: #f59e0b;\n      --accent-light: #fef3c7;\n      --success: #10b981;\n      --success-light: #ecfdf5;\n      --danger: #ef4444;\n      --purple: #8b5cf6;\n      --purple-light: #f5f3ff;\n      --text: #0f172a;\n      --text-muted: #475569;\n      --bg: #f8fafc;\n      --surface: #ffffff;\n      --border: #e2e8f0;\n      --radius: 16px;\n      --shadow: 0 10px 30px -5px rgba(15, 23, 42, 0.07);\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Cairo', sans-serif; }\n    body { background: var(--bg); color: var(--text); line-height: 1.85; padding: 24px 16px; }\n    .container { max-width: 920px; margin: 0 auto; }\n\n    /* Header & Hero */\n    .article-header {\n      background: linear-gradient(135deg, #0f172a 0%, #1e1b4b 50%, #4338ca 100%);\n      color: #ffffff;\n      border-radius: var(--radius);\n      padding: 42px 32px;\n      margin-bottom: 28px;\n      box-shadow: 0 15px 35px -5px rgba(67, 56, 202, 0.28);\n      position: relative;\n      overflow: hidden;\n    }\n    .article-header::after {\n      content: '⚙️';\n      position: absolute;\n      left: 20px;\n      bottom: -15px;\n      font-size: 130px;\n      opacity: 0.12;\n      pointer-events: none;\n    }\n    .badge-series {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(255, 255, 255, 0.18);\n      backdrop-filter: blur(10px);\n      padding: 6px 18px;\n      border-radius: 50px;\n      font-size: 13.5px;\n      font-weight: 800;\n      margin-bottom: 16px;\n      border: 1px solid rgba(255, 255, 255, 0.25);\n    }\n    .article-header h1 {\n      font-size: clamp(23px, 3.2vw, 36px);\n      font-weight: 900;\n      line-height: 1.35;\n      margin-bottom: 14px;\n    }\n    .article-header p {\n      font-size: 17px;\n      opacity: 0.95;\n      max-width: 760px;\n      line-height: 1.7;\n    }\n    .article-meta {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 16px;\n      margin-top: 20px;\n      font-size: 13.5px;\n      color: rgba(255, 255, 255, 0.85);\n      font-weight: 600;\n    }\n\n    /* Content Cards */\n    .content-card {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 32px 28px;\n      margin-bottom: 26px;\n      box-shadow: var(--shadow);\n    }\n    .content-card h2 {\n      font-size: clamp(20px, 2.2vw, 26px);\n      font-weight: 900;\n      color: var(--text);\n      margin-bottom: 18px;\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      border-bottom: 2px solid #f1f5f9;\n      padding-bottom: 12px;\n    }\n    .content-card h3 {\n      font-size: 19px;\n      font-weight: 800;\n      color: var(--primary-dark);\n      margin: 22px 0 10px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .content-card p {\n      font-size: 16.5px;\n      color: var(--text-muted);\n      margin-bottom: 16px;\n      line-height: 1.85;\n    }\n    .content-card strong { color: var(--text); }\n\n    /* Images with Modern Captions */\n    .article-image-box {\n      margin: 26px 0;\n      border-radius: 14px;\n      overflow: hidden;\n      border: 1.5px solid var(--border);\n      background: #0f172a;\n      box-shadow: 0 10px 25px rgba(0,0,0,0.06);\n    }\n    .article-image-box img {\n      width: 100%;\n      height: auto;\n      display: block;\n      transition: transform 0.3s ease;\n    }\n    .article-image-box:hover img {\n      transform: scale(1.01);\n    }\n    .img-caption {\n      padding: 12px 18px;\n      background: #ffffff;\n      color: #475569;\n      font-size: 14px;\n      font-weight: 700;\n      border-top: 1px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n    }\n\n    /* Callout Alert Boxes */\n    .callout {\n      border-right: 5px solid var(--primary);\n      background: var(--primary-light);\n      padding: 18px 22px;\n      border-radius: 10px;\n      margin: 20px 0;\n      font-size: 15.5px;\n      color: #0369a1;\n      line-height: 1.8;\n    }\n    .callout.accent {\n      border-color: var(--accent);\n      background: var(--accent-light);\n      color: #92400e;\n    }\n    .callout.purple {\n      border-color: var(--purple);\n      background: var(--purple-light);\n      color: #6b21a8;\n    }\n    .callout.success {\n      border-color: var(--success);\n      background: var(--success-light);\n      color: #065f46;\n    }\n\n    /* Comparison Grid */\n    .duo-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n      gap: 18px;\n      margin: 22px 0;\n    }\n    .duo-card {\n      background: #f8fafc;\n      border: 1.5px solid var(--border);\n      border-radius: 14px;\n      padding: 22px;\n      transition: transform 0.2s ease, border-color 0.2s ease;\n    }\n    .duo-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--primary);\n    }\n    .duo-card.hardware { border-top: 5px solid #0284c7; }\n    .duo-card.software { border-top: 5px solid #8b5cf6; }\n    .duo-card.firmware { border-top: 5px solid #f59e0b; }\n    .duo-card h4 {\n      font-size: 18px;\n      font-weight: 800;\n      margin-bottom: 10px;\n      color: var(--text);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .duo-card p {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 8px;\n    }\n\n    /* Grid of Components / Apps */\n    .feature-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n      gap: 16px;\n      margin: 20px 0;\n    }\n    .feature-card {\n      background: #ffffff;\n      border: 1.5px solid var(--border);\n      border-radius: 12px;\n      padding: 18px;\n      box-shadow: 0 4px 10px rgba(0,0,0,0.02);\n    }\n    .feature-card h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .feature-card p {\n      font-size: 14px;\n      color: var(--text-muted);\n      margin-bottom: 0;\n    }\n\n    /* Steps & Everyday Scenarios */\n    .steps-container {\n      margin: 24px 0;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n    }\n    .step-item {\n      display: flex;\n      align-items: flex-start;\n      gap: 16px;\n      background: #f8fafc;\n      border: 1.5px solid var(--border);\n      padding: 18px;\n      border-radius: 12px;\n    }\n    .step-number {\n      background: var(--primary);\n      color: #fff;\n      font-weight: 900;\n      font-size: 16px;\n      min-width: 36px;\n      height: 36px;\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-shrink: 0;\n    }\n    .step-text {\n      font-size: 15.5px;\n      color: var(--text);\n      line-height: 1.75;\n    }\n\n    /* Table Styles */\n    .table-container {\n      overflow-x: auto;\n      margin: 24px 0;\n      border-radius: 12px;\n      border: 1.5px solid var(--border);\n    }\n    table { width: 100%; border-collapse: collapse; text-align: right; background: #fff; }\n    th, td { padding: 14px 18px; font-size: 15px; border-bottom: 1px solid var(--border); }\n    th { background: #f1f5f9; font-weight: 800; color: var(--text); }\n    tr:last-child td { border-bottom: none; }\n    tr:hover td { background: #f8fafc; }\n\n    /* Interactive Quiz Section */\n    .quiz-container {\n      background: linear-gradient(180deg, #ffffff 0%, #f5f3ff 100%);\n      border: 2px solid #c4b5fd;\n      border-radius: var(--radius);\n      padding: 34px 28px;\n      margin-bottom: 30px;\n      box-shadow: 0 12px 30px -5px rgba(139, 92, 246, 0.12);\n    }\n    .quiz-title {\n      font-size: 24px;\n      font-weight: 900;\n      color: #4c1d95;\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n    .quiz-desc {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 24px;\n    }\n    .quiz-q {\n      background: #ffffff;\n      border: 1.5px solid #cbd5e1;\n      border-radius: 12px;\n      padding: 20px;\n      margin-bottom: 18px;\n    }\n    .quiz-q-title {\n      font-size: 16.5px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 14px;\n    }\n    .quiz-options {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .opt-btn {\n      padding: 12px 16px;\n      border: 1.5px solid #e2e8f0;\n      background: #f8fafc;\n      border-radius: 10px;\n      cursor: pointer;\n      font-size: 14.5px;\n      font-weight: 600;\n      text-align: right;\n      transition: all 0.2s ease;\n      color: #334155;\n    }\n    .opt-btn:hover {\n      background: #eff6ff;\n      border-color: #8b5cf6;\n      color: #6d28d9;\n    }\n    .opt-btn.correct {\n      background: #dcfce7 !important;\n      border-color: #22c55e !important;\n      color: #15803d !important;\n      font-weight: 800;\n    }\n    .opt-btn.wrong {\n      background: #fee2e2 !important;\n      border-color: #ef4444 !important;\n      color: #b91c1c !important;\n    }\n    .quiz-feedback {\n      margin-top: 10px;\n      font-size: 14px;\n      font-weight: 700;\n      display: none;\n      padding: 8px 12px;\n      border-radius: 6px;\n    }\n\n    /* Footer & Signature */\n    .article-footer {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 28px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 18px;\n    }\n    .author-info {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n    }\n    .author-avatar {\n      width: 52px;\n      height: 52px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #4338ca, #0f172a);\n      color: #fff;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      font-weight: 900;\n      box-shadow: 0 4px 12px rgba(67, 56, 202, 0.3);\n    }\n    .author-details h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n    }\n    .author-details p {\n      font-size: 13.5px;\n      color: var(--text-muted);\n      margin: 0;\n    }\n\n    @media (max-width: 650px) {\n      .article-header { padding: 28px 20px; }\n      .content-card { padding: 22px 18px; }\n      .article-footer { flex-direction: column; text-align: center; }\n      .author-info { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n\n<div class=\"container\">\n\n  <!-- ==========================================\n       1. HERO HEADER\n       ========================================== -->\n  <header class=\"article-header\">\n    <div class=\"badge-series\">\n      <span>💡 معلومة تكنولوجية كل جمعة</span>\n      <span>•</span>\n      <span>برمجة في دقيقة</span>\n    </div>\n    <h1>الفرق بين Hardware وSoftware: إيه الفرق بين الجهاز والبرامج؟</h1>\n    <p>لما بنفتح الكمبيوتر أو اللابتوب، بنستخدم برامج مختلفة علشان نكتب مستندات، ونتصفح الإنترنت، ونلعب الألعاب. لكن هل سألت نفسك قبل كده: إيه الفرق بين قطع الكمبيوتر نفسها والبرامج اللي بتشتغل عليها؟ تعالوا نكتشف معاً سر التكامل المذهل!</p>\n    <div class=\"article-meta\">\n      <span>✍️ بقلم: م. إسلام عاطف (Eslam Atef)</span>\n      <span>⏱️ وقت القراءة: 4 دقائق</span>\n      <span>🎯 المستوى: دليل تأسيسي مبسط لجميع الأعمار</span>\n    </div>\n  </header>\n\n  <!-- ==========================================\n       IMAGE 1: MAIN SHOWCASE\n       ========================================== -->\n  <div class=\"article-image-box\">\n    <img src=\"https://k.top4top.io/p_3951cly8o1.png\" alt=\"الفرق بين الهاردوير والسوفتوير - دليل مبسط لفهم التكنولوجيا\">\n    <div class=\"img-caption\">\n      <span>🔍</span>\n      <span>المكونات المادية (Hardware) والبرمجيات (Software): جناحان لا يستغني أحدهما عن الآخر لتشغيل أي جهاز ذكي</span>\n    </div>\n  </div>\n\n  <!-- ==========================================\n       2. WHAT IS HARDWARE?\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🔌 أولاً: ما هو الـ Hardware؟</h2>\n    <p>كلمة <strong>Hardware</strong> معناها <em>المكونات المادية</em>، وهي الأجزاء الفعلية الحقيقية الموجودة في الكمبيوتر أو أي جهاز إلكتروني، واللي تقدر تشوفها بعينك أو تلمسها بإيدك وتتحسسها.</p>\n    <p>المكونات دي مسؤولة عن تنفيذ العمليات الفيزيائية، ومعالجة البيانات، وعرض النتائج على الشاشة، وتخزين المعلومات، والتواصل بينك وبين الكمبيوتر.</p>\n\n    <h3>🧩 أشهر أمثلة الـ Hardware الحيوية:</h3>\n    <div class=\"feature-grid\">\n      <div class=\"feature-card\">\n        <h4>🖥️ 1. الشاشة (Monitor)</h4>\n        <p>تعرض المعلومات والصور والفيديوهات والنتائج التي يعالجها النظام أمام عينيك.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>⌨️ 2. لوحة المفاتيح (Keyboard)</h4>\n        <p>وحدة إدخال نستخدمها لكتابة الحروف والأرقام وإرسال الأوامر المباشرة للجهاز.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🖱️ 3. الفأرة (Mouse)</h4>\n        <p>تساعدنا في تحريك المؤشر، واختيار العناصر، والتفاعل السلس مع النوافذ والبرامج.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🧠 4. المعالج (CPU)</h4>\n        <p>العقل المفكر؛ ينفّذ تعليمات البرامج والعمليات الحسابية والمنطقية المليارية كل ثانية.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>⚡ 5. ذاكرة الرام (RAM)</h4>\n        <p>مساحة العمل المؤقتة التي تحتفظ بالبيانات والتعليمات التي تحتاجها البرامج أثناء التشغيل.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>💾 6. وحدة التخزين (SSD / HDD)</h4>\n        <p>الخزانة الدائمة لحفظ ملفاتك وبرامجك ونظام التشغيل حتى بعد إغلاق الجهاز وفصل الكهرباء.</p>\n      </div>\n    </div>\n\n    <div class=\"callout\">\n      💡 <strong>القاعدة الذهبية للهاردوير:</strong> كل ما تستطيع لمسه بيديك في عالم التقنية فهو هاردوير!\n    </div>\n  </section>\n\n  <!-- ==========================================\n       3. WHAT IS SOFTWARE?\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>💻 ثانياً: ما هو الـ Software؟</h2>\n    <p>كلمة <strong>Software</strong> معناها <em>البرمجيات</em>، وهي البرامج، والتعليمات، والأكواد الرقمية، والبيانات المرتبطة بتشغيل الجهاز، والتي تحدد للكمبيوتر ماذا يفعل وكيف ينفّذ المهام المطلوبة منه بدقة.</p>\n    <p>البرمجيات مش قطعة مادية تقدر تمسكها بإيدك أو تقيس وزنها؛ لكنها تُخزن كإشارات رقمية، وتعمل باستخدام مكونات الهاردوير، وبتسمح لك بإنجاز كل ما تحتاجه في دراستك وعملك وترفيهك.</p>\n\n    <!-- ==========================================\n         IMAGE 2: SOFTWARE & HARDWARE INTEGRATION\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://l.top4top.io/p_3951znq7u2.png\" alt=\"تناغم البرمجيات مع المكونات المادية لتشغيل الحاسوب\">\n      <div class=\"img-caption\">\n        <span>⚡</span>\n        <span>من الكود إلى الدائرة الكهربائية: كيف تترجم البرمجيات رغبات المستخدم إلى إشارات يستجيب لها الهاردوير فورياً</span>\n      </div>\n    </div>\n\n    <h3>🚀 أشهر تصنيفات وأمثلة الـ Software:</h3>\n    <div class=\"feature-grid\">\n      <div class=\"feature-card\">\n        <h4>🪟 1. أنظمة التشغيل (OS)</h4>\n        <p>مثل Windows وmacOS وLinux، وهي البرامج الأم التي تدير كل موارد الجهاز وتتيح تشغيل باقي التطبيقات.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🌐 2. متصفحات الويب</h4>\n        <p>مثل Google Chrome وEdge وFirefox، بوابتنا اليومية لفتح المواقع وتصفح الإنترنت والتعلم.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>📝 3. برامج الكتابة والمكتب</h4>\n        <p>مثل Microsoft Word وGoogle Docs، لكتابة وتنسيق المستندات والبحوث والتقارير.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🎨 4. برامج التصميم والإبداع</h4>\n        <p>تطبيقات تعديل الصور والرسم والمونتاج، لتوفير بيئة بصرية رائعة لصناع المحتوى.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🎮 5. ألعاب الفيديو</h4>\n        <p>برمجيات تفاعلية متطورة جداً توظف المعالج والرسومات لتقديم تجربة بصرية وصوتية ممتعة.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>📱 6. تطبيقات الهواتف الذكية</h4>\n        <p>برامج التواصل، الآلات الحاسبة، والخرائط الرقمية التي نستخدمها طوال اليوم على الموبايل.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       4. THE CORE DIFFERENCE & COMPARISON\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>⚖️ ما الفرق الجوهري بين Hardware وSoftware؟</h2>\n    <p>الفرق الأساسي والبسيط هو أن <strong>Hardware</strong> هو المكونات المادية التي توفر <em>القدرة والإمكانية</em>، أما <strong>Software</strong> فهو البرامج والتعليمات التي تحدد <em>الأوامر والوظائف</em> المطلوب تنفيذها.</p>\n\n    <div class=\"table-container\">\n      <table>\n        <thead>\n          <tr>\n            <th>وجه المقارنة</th>\n            <th>المكونات المادية (Hardware)</th>\n            <th>البرمجيات (Software)</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>طبيعة المكوّن</strong></td>\n            <td>أجزاء إلكترونية وميكانيكية ملموسة باليد</td>\n            <td>تعليمات وأكواد برمجية رقمية غير ملموسة</td>\n          </tr>\n          <tr>\n            <td><strong>التصنيع والتطوير</strong></td>\n            <td>تُصنع في المصانع وخطوط إنتاج الرقائق</td>\n            <td>تُكتب بواسطة المبرمجين وتُطور بلغات البرمجة</td>\n          </tr>\n          <tr>\n            <td><strong>التآكل والأعطال</strong></td>\n            <td>قد تتلف فيزيائياً بفعل الحرارة أو الصدمات</td>\n            <td>لا تتآكل فيزيائياً، ولكنها قد تحتوي على أخطاء برمجية (Bugs)</td>\n          </tr>\n          <tr>\n            <td><strong>الترقية والتحديث</strong></td>\n            <td>تتطلب استبدال القطعة أو شراء قطعة جديدة</td>\n            <td>تُحدث بسهولة عبر تحميل ملف التحديث أو التثبيت</td>\n          </tr>\n          <tr>\n            <td><strong>أمثلة من حياتنا</strong></td>\n            <td>الشاشة، الكيبورد، الفأرة، المعالج، الرام</td>\n            <td>الويندوز، الوورد، الألعاب، المتصفح، الفوتوشوب</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n\n    <!-- Concrete Duo Examples -->\n    <div class=\"duo-grid\">\n      <div class=\"duo-card hardware\">\n        <h4>🖥️ الشاشة (Hardware)</h4>\n        <p>قطعة زجاجية وإلكترونية تعرض الضوء والألوان.</p>\n      </div>\n      <div class=\"duo-card software\">\n        <h4>🎨 برنامج الرسم (Software)</h4>\n        <p>الأكواد والفرش التي تستخدم تلك الشاشة لترسم لوحتك عليها.</p>\n      </div>\n      <div class=\"duo-card hardware\">\n        <h4>⌨️ الكيبورد (Hardware)</h4>\n        <p>أزرار بلاستيكية وأسلاك تستشعر ضغطة أصابعك.</p>\n      </div>\n      <div class=\"duo-card software\">\n        <h4>📄 برنامج الوورد (Software)</h4>\n        <p>البرنامج الذي يترجم تلك الضغطات إلى كلمات وفقرات منسقة.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       5. CAN ONE WORK WITHOUT THE OTHER?\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🤝 هل يستطيع أحدهما العمل بمفرده دون الآخر؟</h2>\n    \n    <div class=\"duo-grid\">\n      <div class=\"duo-card\">\n        <h4>❓ هل يشتغل الهاردوير بدون سوفتوير؟</h4>\n        <p><strong>مستحيل!</strong> لو جمعت أقوى جهاز كمبيوتر بأغلى معالج ورام في العالم، ودون أن تضع عليه أي برمجيات أو نظام تشغيل، فلن يفعل الجهاز أي شيء سوى أن تدور مراوحه دون أي استجابة؛ فهو جسد بلا روح ينتظر من يوجهه!</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>❓ هل يشتغل السوفتوير بدون هاردوير؟</h4>\n        <p><strong>مستحيل أيضاً!</strong> الأكواد البرمجية لا يمكن أن تسبح في الفراغ؛ تحتاج لمعالج ينفّذ عملياتها، وذاكرة تستضيف بياناتها، وشاشة تعرض نتيجتها. حتى تطبيقات السحاب والإنترنت تعمل على أجهزة هاردوير وسيرفرات فعلية في مراكز البيانات.</p>\n      </div>\n    </div>\n\n    <div class=\"callout success\">\n      🎯 <strong>علاقة تكامل لا تنفصل:</strong> الهاردوير والسوفتوير مثل عازف البيانو وآلة البيانو؛ الآلة وحدها لن تعزف صوتاً، وعازف البيانو دون آلة لن يسمع أحداً نغماته!\n    </div>\n  </section>\n\n  <!-- ==========================================\n       6. EVERYDAY SCENARIO: A SCHOOL ESSAY\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🎬 سيناريو من حياتنا اليومية: كتابة بحث مدرسي</h2>\n    <p>تخيّل أنك جلست أمام جهازك لكتابة موضوع تعبير للمدرسة.. كيف يتعاون الهاردوير والسوفتوير في كل ثانية؟</p>\n\n    <div class=\"steps-container\">\n      <div class=\"step-item\">\n        <div class=\"step-number\">1</div>\n        <div class=\"step-text\">\n          <strong>إدخال الحروف (Hardware):</strong> تضغط بأصابعك على أزرار لوحة المفاتيح.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">2</div>\n        <div class=\"step-text\">\n          <strong>الاستقبال والتنسيق (Software):</strong> برنامج الكتابة (Word) يستقبل الإشارات ويحدد حجم الخط واللون والمسافات.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">3</div>\n        <div class=\"step-text\">\n          <strong>الحساب والمعالجة (Hardware):</strong> المعالج المركزي (CPU) ينفذ التعليمات ويوجه بتنظيم موقع الكلمات.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">4</div>\n        <div class=\"step-text\">\n          <strong>الاحتفاظ السريع (Hardware):</strong> ذاكرة الرام (RAM) تحتفظ بما كتبته لحظة بلحظة لسرعة التعديل.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">5</div>\n        <div class=\"step-text\">\n          <strong>العرض البصري (Hardware):</strong> الشاشة تضيء البكسلات لتشاهد الجملة واضحة أمام عينيك.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">6</div>\n        <div class=\"step-text\">\n          <strong>الحفظ الآمن (Hardware + Software):</strong> تضغط أمر «حفظ» في البرنامج، فيقوم الهاردوير بكتابة الملف داخل قرص الـ SSD ليبقى محفوظاً للأبد!\n        </div>\n      </div>\n    </div>\n\n    <!-- ==========================================\n         IMAGE 3: SYSTEM ECOSYSTEM\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://a.top4top.io/p_3951x9trj3.png\" alt=\"المنظومة المتكاملة للكمبيوتر بين العتاد والبرامج\">\n      <div class=\"img-caption\">\n        <span>🔄</span>\n        <span>المنظومة الحاسوبية المتكاملة: خطوات متتابعة تبدأ من المستخدم وتمر عبر طبقات البرامج وصولاً إلى الإلكترونيات الدقيقة</span>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       7. WHAT IS FIRMWARE? (THE HIDDEN HERO)\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🛠️ مصطلح ثالث مهم: ما هو الـ Firmware؟</h2>\n    <p>أثناء رحلتك في التكنولوجيا، ستسمع كثيراً عن كلمة <strong>Firmware</strong> (البرمجيات الثابتة). فما هو بالضبط وما فرقه عن السوفتوير العادي؟</p>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card firmware\">\n        <h4>⚡ البرمجيات الثابتة (Firmware)</h4>\n        <p>هي برمجيات متخصصة منخفضة المستوى تُبرمج وتُدمج مباشرة داخل شريحة إلكترونية دائمة (ROM) على اللوحة الأم أو الراوتر أو الطابعة، ومهمتها تشغيل القطعة نفسها وإعطاؤها التعليمات الأساسية لبدء الحياة والتواصل مع النظام (مثل نظام BIOS أو UEFI في الكمبيوتر).</p>\n      </div>\n      <div class=\"duo-card software\">\n        <h4>💻 البرمجيات العامة (Software)</h4>\n        <p>هو المصطلح العام والشامل الذي يضم كافة التطبيقات والبرامج وأنظمة التشغيل التي يمكن للمستخدم تثبيتها، وتعديلها، أو حذفها بكل حرية واستخدامها لأداء مهامه اليومية.</p>\n      </div>\n    </div>\n\n    <div class=\"callout accent\">\n      💡 <strong>تبسيط ذكي:</strong> الـ Firmware هو السوفتوير الخاص بالقطعة نفسها لكي تفهم ما هي وظيفتها الأساسية بمجرد تشغيل الكهرباء عليها!\n    </div>\n  </section>\n\n  <!-- ==========================================\n       8. EMBEDDED INTERACTIVE QUIZ\n       ========================================== -->\n  <section class=\"quiz-container\">\n    <div class=\"quiz-title\">\n      <span>🧠</span>\n      <span>اختبر معلوماتك: هل تميز بين Hardware وSoftware؟</span>\n    </div>\n    <p class=\"quiz-desc\">اضغط على الإجابة الصحيحة واكتشف تقييمك فورياً:</p>\n\n    <!-- Q1 -->\n    <div class=\"quiz-q\" id=\"q1\">\n      <div class=\"quiz-q-title\">1. هل الشاشة تعتبر Hardware أم Software؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, true, 'إجابة ممتازة! الشاشة مكوّن مادي نراه ونلمسه باليد لذا هي Hardware.')\">Hardware (مكون مادي)</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, false, 'إجابة خاطئة؛ البرمجيات هي الأكواد والبرامج، بينما الشاشة جهاز مادي.')\">Software (برمجيات)</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q1-fb\"></div>\n    </div>\n\n    <!-- Q2 -->\n    <div class=\"quiz-q\" id=\"q2\">\n      <div class=\"quiz-q-title\">2. هل نظام التشغيل Windows يعتبر Hardware؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, false, 'إجابة غير صحيحة؛ الويندوز لا نستطيع لمسه بيدك فهو نظام تشغيل رقمي.')\">نعم، هو مكوّن مادي</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, true, 'رائع جداً! الويندوز هو نظام تشغيل (Software) يدير موارد الجهاز.')\">لا، هو برمجيات (Software)</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q2-fb\"></div>\n    </div>\n\n    <!-- Q3 -->\n    <div class=\"quiz-q\" id=\"q3\">\n      <div class=\"quiz-q-title\">3. ما الفرق بين ذاكرة الرام (RAM) ومتصفح Google Chrome؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, true, 'صحيح تماماً! الرام شريحة هاردوير مادية، وجوجل كروم برنامج سوفتوير يعمل بداخلها.')\">الرام هي Hardware وكروم هو Software</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, false, 'إجابة غير صحيحة؛ الاثنان ليسا من نفس النوع.')\">كلاهما سوفتوير برمجي</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q3-fb\"></div>\n    </div>\n\n    <!-- Q4 -->\n    <div class=\"quiz-q\" id=\"q4\">\n      <div class=\"quiz-q-title\">4. هل يمكن لأحدث وأقوى كمبيوتر أن يعمل دون أي سوفتوير أو برمجيات؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q4', this, true, 'إجابة عبقرية! الهاردوير يحتاج تعليمات برمجية توجهه وتخبره ماذا يفعل.')\">لا، يحتاج برمجيات تعطيه التعليمات للعمل</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q4', this, false, 'غير صحيح؛ مهما كانت قوة القطع، لا يمكنها العمل دون سوفتوير.')\">نعم، الهاردوير القوي يعمل بمفرده</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q4-fb\"></div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       9. ARTICLE FOOTER & SIGNATURE\n       ========================================== -->\n  <footer class=\"article-footer\">\n    <div class=\"author-info\">\n      <div class=\"author-avatar\">إ</div>\n      <div class=\"author-details\">\n        <h4>م. إسلام عاطف | Eslam Atef</h4>\n        <p>مهندس برمجيات ومدرب معتمد في البرمجة والذكاء الاصطناعي للأطفال والشباب</p>\n      </div>\n    </div>\n    <div style=\"font-size: 13.5px; color: #64748b; font-weight: 700;\">\n      🚀 برمجة في دقيقة — كل ما فهمت العلاقة بين الهاردوير والسوفتوير، خطوت خطوة أوسع نحو عالم البرمجة الاحترافية.\n    </div>\n  </footer>\n\n</div>\n\n<script>\n  function checkAnswer(qId, btn, isCorrect, explanation) {\n    const parent = document.getElementById(qId);\n    const buttons = parent.querySelectorAll('.opt-btn');\n    const fb = document.getElementById(qId + '-fb');\n\n    buttons.forEach(b => {\n      b.disabled = true;\n      b.style.cursor = 'default';\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      fb.style.display = 'block';\n      fb.style.background = '#dcfce7';\n      fb.style.color = '#15803d';\n      fb.innerHTML = '✅ ' + explanation;\n    } else {\n      btn.classList.add('wrong');\n      fb.style.display = 'block';\n      fb.style.background = '#fee2e2';\n      fb.style.color = '#b91c1c';\n      fb.innerHTML = '❌ ' + explanation;\n    }\n  }\n</script>\n\n</body>\n</html>\n", "status": "منشور", "isPublished": true, "imageUrl": "https://k.top4top.io/p_3951cly8o1.png", "image": "https://k.top4top.io/p_3951cly8o1.png", "createdAt": "2026-10-25T12:00:00Z", "views": 140, "likes": 52},
    {"id": "article_computer_networks", "title": "يعني إيه شبكة كمبيوتر؟ وإزاي الأجهزة بتكلم بعضها؟", "category": "علوم الحاسب والبرمجة", "htmlCode": "<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>يعني إيه شبكة كمبيوتر؟ وإزاي الأجهزة بتكلم بعضها؟ | برمجة في دقيقة</title>\n  \n  <meta name=\"description\" content=\"دليل مبسط وشامل لفهم شبكات الكمبيوتر: أنواعها LAN و MAN و WAN، الفرق بين الراوتر والسويتش، كيف تنتقل حزم البيانات، ولماذا لا يعني الاتصال بنفس الواي فاي مشاركة الملفات تلقائياً، مع اختبار تفاعلي.\">\n  <meta name=\"keywords\" content=\"شبكات الكمبيوتر, أنواع الشبكات, الفرق بين LAN و WAN, كيف تعمل الشبكات, برمجة في دقيقة, إسلام عاطف, أمان الواي فاي\">\n  <meta name=\"author\" content=\"م. إسلام عاطف | Eslam Atef\">\n  \n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800;900&display=swap\" rel=\"stylesheet\">\n\n  <style>\n    :root {\n      --primary: #0284c7;\n      --primary-dark: #0369a1;\n      --primary-light: #f0f9ff;\n      --secondary: #0f172a;\n      --accent: #f59e0b;\n      --accent-light: #fef3c7;\n      --success: #10b981;\n      --success-light: #ecfdf5;\n      --danger: #ef4444;\n      --purple: #8b5cf6;\n      --purple-light: #f5f3ff;\n      --teal: #0d9488;\n      --teal-light: #f0fdfa;\n      --text: #0f172a;\n      --text-muted: #475569;\n      --bg: #f8fafc;\n      --surface: #ffffff;\n      --border: #e2e8f0;\n      --radius: 16px;\n      --shadow: 0 10px 30px -5px rgba(15, 23, 42, 0.07);\n    }\n\n    * { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Cairo', sans-serif; }\n    body { background: var(--bg); color: var(--text); line-height: 1.85; padding: 24px 16px; }\n    .container { max-width: 920px; margin: 0 auto; }\n\n    /* Header & Hero */\n    .article-header {\n      background: linear-gradient(135deg, #064e3b 0%, #0d9488 50%, #0284c7 100%);\n      color: #ffffff;\n      border-radius: var(--radius);\n      padding: 42px 32px;\n      margin-bottom: 28px;\n      box-shadow: 0 15px 35px -5px rgba(13, 148, 136, 0.28);\n      position: relative;\n      overflow: hidden;\n    }\n    .article-header::after {\n      content: '🌐';\n      position: absolute;\n      left: 20px;\n      bottom: -15px;\n      font-size: 130px;\n      opacity: 0.12;\n      pointer-events: none;\n    }\n    .badge-series {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      background: rgba(255, 255, 255, 0.18);\n      backdrop-filter: blur(10px);\n      padding: 6px 18px;\n      border-radius: 50px;\n      font-size: 13.5px;\n      font-weight: 800;\n      margin-bottom: 16px;\n      border: 1px solid rgba(255, 255, 255, 0.25);\n    }\n    .article-header h1 {\n      font-size: clamp(23px, 3.2vw, 36px);\n      font-weight: 900;\n      line-height: 1.35;\n      margin-bottom: 14px;\n    }\n    .article-header p {\n      font-size: 17px;\n      opacity: 0.95;\n      max-width: 760px;\n      line-height: 1.7;\n    }\n    .article-meta {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 16px;\n      margin-top: 20px;\n      font-size: 13.5px;\n      color: rgba(255, 255, 255, 0.85);\n      font-weight: 600;\n    }\n\n    /* Content Cards */\n    .content-card {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 32px 28px;\n      margin-bottom: 26px;\n      box-shadow: var(--shadow);\n    }\n    .content-card h2 {\n      font-size: clamp(20px, 2.2vw, 26px);\n      font-weight: 900;\n      color: var(--text);\n      margin-bottom: 18px;\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      border-bottom: 2px solid #f1f5f9;\n      padding-bottom: 12px;\n    }\n    .content-card h3 {\n      font-size: 19px;\n      font-weight: 800;\n      color: var(--teal);\n      margin: 22px 0 10px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .content-card p {\n      font-size: 16.5px;\n      color: var(--text-muted);\n      margin-bottom: 16px;\n      line-height: 1.85;\n    }\n    .content-card strong { color: var(--text); }\n\n    /* Images with Modern Captions */\n    .article-image-box {\n      margin: 26px 0;\n      border-radius: 14px;\n      overflow: hidden;\n      border: 1.5px solid var(--border);\n      background: #0f172a;\n      box-shadow: 0 10px 25px rgba(0,0,0,0.06);\n    }\n    .article-image-box img {\n      width: 100%;\n      height: auto;\n      display: block;\n      transition: transform 0.3s ease;\n    }\n    .article-image-box:hover img {\n      transform: scale(1.01);\n    }\n    .img-caption {\n      padding: 12px 18px;\n      background: #ffffff;\n      color: #475569;\n      font-size: 14px;\n      font-weight: 700;\n      border-top: 1px solid var(--border);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      gap: 8px;\n    }\n\n    /* Callout Alert Boxes */\n    .callout {\n      border-right: 5px solid var(--teal);\n      background: var(--teal-light);\n      padding: 18px 22px;\n      border-radius: 10px;\n      margin: 20px 0;\n      font-size: 15.5px;\n      color: #115e59;\n      line-height: 1.8;\n    }\n    .callout.accent {\n      border-color: var(--accent);\n      background: var(--accent-light);\n      color: #92400e;\n    }\n    .callout.primary {\n      border-color: var(--primary);\n      background: var(--primary-light);\n      color: #0369a1;\n    }\n    .callout.danger {\n      border-color: var(--danger);\n      background: #fef2f2;\n      color: #991b1b;\n    }\n\n    /* Comparison Grid & Types Cards */\n    .duo-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));\n      gap: 18px;\n      margin: 22px 0;\n    }\n    .duo-card {\n      background: #f8fafc;\n      border: 1.5px solid var(--border);\n      border-radius: 14px;\n      padding: 22px;\n      transition: transform 0.2s ease, border-color 0.2s ease;\n    }\n    .duo-card:hover {\n      transform: translateY(-2px);\n      border-color: var(--teal);\n    }\n    .duo-card.lan { border-top: 5px solid #0d9488; }\n    .duo-card.man { border-top: 5px solid #0284c7; }\n    .duo-card.wan { border-top: 5px solid #8b5cf6; }\n    .duo-card h4 {\n      font-size: 18px;\n      font-weight: 800;\n      margin-bottom: 10px;\n      color: var(--text);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .duo-card p {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 8px;\n    }\n\n    /* Feature Cards */\n    .feature-grid {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));\n      gap: 16px;\n      margin: 20px 0;\n    }\n    .feature-card {\n      background: #ffffff;\n      border: 1.5px solid var(--border);\n      border-radius: 12px;\n      padding: 18px;\n      box-shadow: 0 4px 10px rgba(0,0,0,0.02);\n    }\n    .feature-card h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .feature-card p {\n      font-size: 14px;\n      color: var(--text-muted);\n      margin-bottom: 0;\n    }\n\n    /* Steps Flow */\n    .steps-container {\n      margin: 24px 0;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n    }\n    .step-item {\n      display: flex;\n      align-items: flex-start;\n      gap: 16px;\n      background: #f8fafc;\n      border: 1.5px solid var(--border);\n      padding: 18px;\n      border-radius: 12px;\n    }\n    .step-number {\n      background: var(--teal);\n      color: #fff;\n      font-weight: 900;\n      font-size: 16px;\n      min-width: 36px;\n      height: 36px;\n      border-radius: 50%;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      flex-shrink: 0;\n    }\n    .step-text {\n      font-size: 15.5px;\n      color: var(--text);\n      line-height: 1.75;\n    }\n\n    /* Checklist Box */\n    .checklist-card {\n      background: #f0fdf4;\n      border: 2px solid #86efac;\n      border-radius: 14px;\n      padding: 24px;\n      margin: 20px 0;\n    }\n    .checklist-card h4 {\n      font-size: 17.5px;\n      font-weight: 900;\n      color: #166534;\n      margin-bottom: 14px;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n    .checklist-list {\n      list-style: none;\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .checklist-list li {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n      font-size: 15px;\n      color: #14532d;\n      font-weight: 600;\n    }\n\n    /* Table Styles */\n    .table-container {\n      overflow-x: auto;\n      margin: 24px 0;\n      border-radius: 12px;\n      border: 1.5px solid var(--border);\n    }\n    table { width: 100%; border-collapse: collapse; text-align: right; background: #fff; }\n    th, td { padding: 14px 18px; font-size: 15px; border-bottom: 1px solid var(--border); }\n    th { background: #f1f5f9; font-weight: 800; color: var(--text); }\n    tr:last-child td { border-bottom: none; }\n    tr:hover td { background: #f8fafc; }\n\n    /* Interactive Quiz Section */\n    .quiz-container {\n      background: linear-gradient(180deg, #ffffff 0%, #f0fdfa 100%);\n      border: 2px solid #99f6e4;\n      border-radius: var(--radius);\n      padding: 34px 28px;\n      margin-bottom: 30px;\n      box-shadow: 0 12px 30px -5px rgba(13, 148, 136, 0.12);\n    }\n    .quiz-title {\n      font-size: 24px;\n      font-weight: 900;\n      color: #115e59;\n      margin-bottom: 8px;\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n    .quiz-desc {\n      font-size: 15px;\n      color: var(--text-muted);\n      margin-bottom: 24px;\n    }\n    .quiz-q {\n      background: #ffffff;\n      border: 1.5px solid #cbd5e1;\n      border-radius: 12px;\n      padding: 20px;\n      margin-bottom: 18px;\n    }\n    .quiz-q-title {\n      font-size: 16.5px;\n      font-weight: 800;\n      color: var(--text);\n      margin-bottom: 14px;\n    }\n    .quiz-options {\n      display: flex;\n      flex-direction: column;\n      gap: 10px;\n    }\n    .opt-btn {\n      padding: 12px 16px;\n      border: 1.5px solid #e2e8f0;\n      background: #f8fafc;\n      border-radius: 10px;\n      cursor: pointer;\n      font-size: 14.5px;\n      font-weight: 600;\n      text-align: right;\n      transition: all 0.2s ease;\n      color: #334155;\n    }\n    .opt-btn:hover {\n      background: #eff6ff;\n      border-color: #0d9488;\n      color: #0f766e;\n    }\n    .opt-btn.correct {\n      background: #dcfce7 !important;\n      border-color: #22c55e !important;\n      color: #15803d !important;\n      font-weight: 800;\n    }\n    .opt-btn.wrong {\n      background: #fee2e2 !important;\n      border-color: #ef4444 !important;\n      color: #b91c1c !important;\n    }\n    .quiz-feedback {\n      margin-top: 10px;\n      font-size: 14px;\n      font-weight: 700;\n      display: none;\n      padding: 8px 12px;\n      border-radius: 6px;\n    }\n\n    /* Footer & Signature */\n    .article-footer {\n      background: var(--surface);\n      border: 1.5px solid var(--border);\n      border-radius: var(--radius);\n      padding: 28px;\n      display: flex;\n      flex-wrap: wrap;\n      align-items: center;\n      justify-content: space-between;\n      gap: 18px;\n    }\n    .author-info {\n      display: flex;\n      align-items: center;\n      gap: 14px;\n    }\n    .author-avatar {\n      width: 52px;\n      height: 52px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #0d9488, #0284c7);\n      color: #fff;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 22px;\n      font-weight: 900;\n      box-shadow: 0 4px 12px rgba(13, 148, 136, 0.3);\n    }\n    .author-details h4 {\n      font-size: 16px;\n      font-weight: 800;\n      color: var(--text);\n    }\n    .author-details p {\n      font-size: 13.5px;\n      color: var(--text-muted);\n      margin: 0;\n    }\n\n    @media (max-width: 650px) {\n      .article-header { padding: 28px 20px; }\n      .content-card { padding: 22px 18px; }\n      .article-footer { flex-direction: column; text-align: center; }\n      .author-info { flex-direction: column; }\n    }\n  </style>\n</head>\n<body>\n\n<div class=\"container\">\n\n  <!-- ==========================================\n       1. HERO HEADER\n       ========================================== -->\n  <header class=\"article-header\">\n    <div class=\"badge-series\">\n      <span>💡 معلومة تكنولوجية كل جمعة</span>\n      <span>•</span>\n      <span>برمجة في دقيقة</span>\n    </div>\n    <h1>يعني إيه شبكة كمبيوتر؟ وإزاي الأجهزة بتكلم بعضها؟</h1>\n    <p>هل لاحظت قبل كده إنك تقدر تطبع مستند من اللابتوب باستخدام طابعة في الغرفة المجاورة، أو تبعت ملفات بين الأجهزة، أو تتصل بالإنترنت من الموبايل والكمبيوتر؟ كل ده بيعتمد على عالم شبكات الكمبيوتر الساحر!</p>\n    <div class=\"article-meta\">\n      <span>✍️ بقلم: م. إسلام عاطف (Eslam Atef)</span>\n      <span>⏱️ وقت القراءة: 5 دقائق</span>\n      <span>🎯 المستوى: دليل شامل للمبتدئين واليافعين والمهتمين بالتقنية</span>\n    </div>\n  </header>\n\n  <!-- ==========================================\n       IMAGE 1: MAIN SHOWCASE\n       ========================================== -->\n  <div class=\"article-image-box\">\n    <img src=\"https://g.top4top.io/p_3951wn90y1.png\" alt=\"شبكات الكمبيوتر - كيف تتواصل الأجهزة وتتبادل البيانات\">\n    <div class=\"img-caption\">\n      <span>🌐</span>\n      <span>عالم الشبكات: شريان التواصل الحديث الذي يربط مليارات الأجهزة حول الكوكب في أجزاء من الثانية</span>\n    </div>\n  </div>\n\n  <!-- ==========================================\n       2. WHAT IS A COMPUTER NETWORK?\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🎯 أولاً: ما هي شبكة الكمبيوتر (Computer Network)؟</h2>\n    <p>شبكة الكمبيوتر هي <strong>مجموعة من الأجهزة المتصلة ببعضها</strong> من خلال وسائل اتصال سلكية أو لاسلكية، بهدف تبادل البيانات، ومشاركة الموارد والخدمات، بدل ما يكون كل جهاز جزيرة منعزلة تماماً عن العالم.</p>\n    <p>الأجهزة المتصلة بالشبكة لا تقتصر على الكمبيوتر فقط؛ بل تشمل منظومة ذكية متكاملة تضم:</p>\n\n    <div class=\"feature-grid\">\n      <div class=\"feature-card\">\n        <h4>💻 أجهزة الكمبيوتر واللابتوب</h4>\n        <p>محطات العمل الرئيسية للطلاب والموظفين لإرسال واستقبال البيانات والبرامج.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>📱 الهواتف الذكية والتابلت</h4>\n        <p>أجهزة محمولة تتصل عبر الواي فاي للوصول إلى الخدمات والإنترنت لحظياً.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🖨️ الطابعات الشبكية</h4>\n        <p>طابعة واحدة يستطيع عشرات الأشخاص في المنزل أو المكتب الطباعة عليها عن بعد.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🗄️ الخوادم المركزية (Servers)</h4>\n        <p>أجهزة كمبيوتر عملاقة تخزن المواقع والملفات وتقدم الخدمات لكافة المشتركين.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>📹 الكاميرات وأجهزة المنزل الذكي</h4>\n        <p>كاميرات المراقبة، التلفزيونات الذكية، والمساعدات الصوتية كـ Alexa وغيرها.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🎮 منصات الألعاب (Consoles)</h4>\n        <p>للاتصال بالمخوادم واللعب الجماعي المباشر مع أصدقائك حول العالم.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       3. WHY DO WE USE NETWORKS?\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>💡 ثانياً: لماذا نستخدم الشبكات؟ 4 فوائد كبرى</h2>\n    <p>تخيل كيف كانت الحياة لو اضطررت لنقل فلاشة USB في كل مرة تريد فيها إرسال صورة أو ملف إلى زميلك! تقدم الشبكات 4 مزايا غيرت شكل الحياة:</p>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card\">\n        <h4>📁 1. مشاركة الملفات السريعة</h4>\n        <p>نقل المستندات والصور والفيديوهات بين الأجهزة المتصلة مباشرة وبأعلى سرعة وبضغطة زر واحدة وفق الصلاحيات المتاحة.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>🖨️ 2. مشاركة الموارد (Resource Sharing)</h4>\n        <p>توفير التكاليف الباهظة؛ فبدل شراء 20 طابعة لعشرين غرفة، نشتري طابعة شبكية واحدة ممتازة يشترك فيها الجميع.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>💬 3. التواصل الحي والمباشر</h4>\n        <p>دعم كافة برامج المحادثة الفورية، ومكالمات الفيديو، والبريد الإلكتروني، والاجتماعات التفاعلية عبر القارات.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>🌍 4. الوصول المشترك للإنترنت</h4>\n        <p>خط إنترنت منزلي واحد من خلال جهاز الراوتر يوزع الاتصال على كل أفراد العائلة بكفاءة وسلاسة.</p>\n      </div>\n    </div>\n\n    <div class=\"callout accent\">\n      ⚠️ <strong>حقيقة مهمة جداً:</strong> الشبكة المحلية والإنترنت ليسا نفس الشيء! شبكتك المنزلية تستطيع العمل ومشاركة الملفات والطابعات بين أجهزة البيت حتى لو انقطع سلك الإنترنت القادم من شركة الاتصالات!\n    </div>\n  </section>\n\n  <!-- ==========================================\n       4. TYPES OF NETWORKS (LAN, MAN, WAN)\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🗺️ ثالثاً: ما هي أنواع شبكات الكمبيوتر حسب النطاق الجغرافي؟</h2>\n    <p>من أشهر الطرق لتصنيف الشبكات تقسيمها وفق المساحة الجغرافية التي تغطيها وتصل إليها الأجهزة:</p>\n\n    <!-- ==========================================\n         IMAGE 2: NETWORK TOPOLOGY & TYPES\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://h.top4top.io/p_39512s7oy2.png\" alt=\"أنواع شبكات الكمبيوتر LAN و MAN و WAN\">\n      <div class=\"img-caption\">\n        <span>📡</span>\n        <span>مقارنة النطاقات الجغرافية: من الشبكة المحلية داخل غرفتك (LAN) إلى الشبكة العالمية المترامية (WAN)</span>\n      </div>\n    </div>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card lan\">\n        <h4>🏠 1. الشبكة المحلية (LAN)</h4>\n        <p><strong>Local Area Network:</strong> تربط الأجهزة داخل مساحة محدودة وصغيرة نسبياً كمنزل، أو معمل كمبيوتر مدرسي، أو مبنى شركة واحد. تتميز بسرعتها الفائقة وتكلفتها الاقتصادية وسهولة إدارتها.</p>\n      </div>\n      <div class=\"duo-card man\">\n        <h4>🏙️ 2. شبكة النطاق الحضري (MAN)</h4>\n        <p><strong>Metropolitan Area Network:</strong> شبكة تغطي مساحة جغرافية متوسطة بحجم مدينة كاملة، وتُستخدم عادة لربط فروع جامعة موزعة داخل المدينة أو ربط بنوك أو مستشفيات بمقر مركزي.</p>\n      </div>\n      <div class=\"duo-card wan\">\n        <h4>🌐 3. الشبكة واسعة النطاق (WAN)</h4>\n        <p><strong>Wide Area Network:</strong> شبكة عملاقة عابرة للحدود تربط أجهزة وشبكات عبر دول وقارات متباعدة، وأعظم مثال حي عليها هو <strong>الإنترنت العالمي</strong> الذي نستخدمه جميعاً.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       5. HARDWARE OF NETWORKING\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🔌 رابعاً: كيف تتصل الأجهزة؟ وما هي الأجهزة المساعدة؟</h2>\n    <p>هناك وسيلتان رئيسيتان لتوصيل الأجهزة بالشبكة:</p>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card\">\n        <h4>🔗 الاتصال السلكي (Wired)</h4>\n        <p>يستخدم كابلات النحاس والفايبر مثل كابلات <strong>Ethernet (RJ45)</strong>؛ ويتميز بأقصى درجات الثبات والسرعة العالية وعدم التأثر بالحواجز، وهو مفضل للألعاب والسيرفرات.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>📶 الاتصال اللاسلكي (Wireless)</h4>\n        <p>يستخدم موجات الراديو الكهرومغناطيسية مثل <strong>Wi-Fi</strong>؛ يمنحك حرية الحركة والتنقل في أي مكان بالمنزل بالموبايل واللابتوب دون أسلاك معقدة.</p>\n      </div>\n    </div>\n\n    <h3>🎛️ أبطال الشبكة: الأجهزة التي توجه البيانات وتنظم المرور</h3>\n    <div class=\"feature-grid\">\n      <div class=\"feature-card\">\n        <h4>📡 1. الراوتر (Router)</h4>\n        <p>العقل المفكر لتوجيه البيانات؛ يربط شبكتك المنزلية الداخلية بشبكة الإنترنت الخارجية ويختار أفضل مسار للبيانات.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>🔀 2. المبدّل (Switch)</h4>\n        <p>الموزع الذكي داخل الشبكة السلكية؛ يربط أجهزة الكمبيوتر ببعضها ويرسل البيانات بدقة للجهاز المعني فقط.</p>\n      </div>\n      <div class=\"feature-card\">\n        <h4>📶 3. نقطة الوصول (Access Point)</h4>\n        <p>محطة بث الإشارة اللاسلكية؛ تتيح للأجهزة اللاسلكية كالهواتف واللابتوبات الاتصال بالشبكة السلكية عن بعد.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       6. HOW DATA TRAVELS BETWEEN DEVICES\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>📦 خامساً: كيف تنتقل البيانات بين الأجهزة في الكواليس؟</h2>\n    <p>تخيّل أنك أرسلت ملفاً أو صورة لصديقك على نفس الشبكة.. ماذا يحدث في جزء من الثانية؟</p>\n\n    <div class=\"steps-container\">\n      <div class=\"step-item\">\n        <div class=\"step-number\">1</div>\n        <div class=\"step-text\">\n          <strong>التقطيع والتجهيز (Packetization):</strong> جهازك لا يرسل الملف ككتلة واحدة ضخمة؛ بل يقسمه إلى آلاف القطع الصغيرة تسمى <strong>حزم بيانات (Packets)</strong>، ويضع على كل حزمة عنوان الجهاز المرسل (IP) وعنوان المستقبل ورقم ترتيب الحزمة.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">2</div>\n        <div class=\"step-text\">\n          <strong>الانطلاق عبر الوسيط:</strong> تنطلق الحزم عبر السلك النحاسي أو موجات الواي فاي في صورة إشارات رقمية (0 و 1).\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">3</div>\n        <div class=\"step-text\">\n          <strong>التوجيه والمطابقة:</strong> جهاز السويتش أو الراوتر يقرأ عنوان المستقبل ويوجه الحزم إلى المنفذ الصحيح نحو الجهاز الهدف.\n        </div>\n      </div>\n      <div class=\"step-item\">\n        <div class=\"step-number\">4</div>\n        <div class=\"step-text\">\n          <strong>الاستقبال وإعادة التجميع:</strong> يستلم جهاز صديقك الحزم، ويتأكد من سلامتها وعدم ضياع أي حزمة، ثم يعيد ترتيبها ودمجها ليظهر الملف أمامه كاملاً وسليماً!\n        </div>\n      </div>\n    </div>\n\n    <!-- ==========================================\n         IMAGE 3: DATA FLOW & CYBERSECURITY\n         ========================================== -->\n    <div class=\"article-image-box\">\n      <img src=\"https://i.top4top.io/p_3951cdngl3.png\" alt=\"مسار حزم البيانات وحماية الشبكة وأمان المعلومات\">\n      <div class=\"img-caption\">\n        <span>🔒</span>\n        <span>حزم البيانات وأمان الشبكات: بروتوكولات التشفير والجدران النارية تضمن وصول بياناتك سالمة ومحمية من التسلل</span>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       7. COMMON MISCONCEPTIONS\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🤔 سادساً: أسئلة شائعة وخرافات حول الشبكات</h2>\n\n    <div class=\"duo-grid\">\n      <div class=\"duo-card\">\n        <h4>هل الاتصال بنفس الواي فاي يتيح تبادل الملفات تلقائياً؟</h4>\n        <p><strong>مش بالضرورة إطلاقاً!</strong> الاتصال بنفس الشبكة يعني أن الأجهزة في نفس البيئة اللاسلكية، ولكن مشاركة الملفات تحتاج لتفعيل إعدادات المشاركة، وتحديد صلاحيات الوصول وكلمات المرور. كما أن بعض الشبكات تستخدم خاصية عزل الأجهزة (Client Isolation) لمنع رؤية الأجهزة لبعضها حمايةً لخصوصية المستخدمين.</p>\n      </div>\n      <div class=\"duo-card\">\n        <h4>ما هو الفرق الحقيقي بين كلمة «شبكة» و«إنترنت»؟</h4>\n        <p>الشبكة مفهوم عام يطلق على أي جهازين أو أكثر متصلين ببعضهما (مثل لابتوبك وطابعتك). أما <strong>الإنترنت</strong> فهو شبكة الشبكات العالمية الضخمة التي تربط مليارات الشبكات المنفصلة حول العالم ببعضها عبر كابلات بحرية وأقمار صناعية.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       8. NETWORK SECURITY TIPS\n       ========================================== -->\n  <section class=\"content-card\">\n    <h2>🛡️ سابعاً: كيف تحافظ على أمان شبكتك المنزلية وأجهزتك؟</h2>\n    <p>بما أن الشبكة تتيح التواصل، فإنها أيضاً قد تكون باباً للمخترقين إن لم تؤمنها جيداً. إليك قائمة الممارسات الذهبية:</p>\n\n    <div class=\"checklist-card\">\n      <h4>🔒 الدليل العملي لأمان شبكتك:</h4>\n      <ul class=\"checklist-list\">\n        <li>🔑 اختر كلمة مرور معقدة وطويلة لشبكة الواي فاي المنزلية، ولا تستخدم أرقام الهواتف أو تواريخ الميلاد.</li>\n        <li>🛡️ غيّر كلمة مرور لوحة تحكم الراوتر الافتراضية (Admin/Admin) فوراً بكلمة سر قوية وخاصة بك.</li>\n        <li>🔄 احرص دائماً على تحديث نظام تشغيل أجهزتك (Windows / Android / iOS) لسد الثغرات الأمنية أولاً بأول.</li>\n        <li>⛔ تجنّب تماماً الاتصال بشبكات الواي فاي العامة المفتوحة في المقاهي والشارع لإجراء معاملات بنكية أو فتح حسابات حساسة.</li>\n        <li>🛑 لا تقم بتفعيل مشاركة الملفات دون وضع كلمة مرور سرية تحدد من يمكنه فتح المجلد.</li>\n      </ul>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       9. EMBEDDED INTERACTIVE QUIZ\n       ========================================== -->\n  <section class=\"quiz-container\">\n    <div class=\"quiz-title\">\n      <span>🧠</span>\n      <span>اختبر معلوماتك: كم تفهم من عالم شبكات الكمبيوتر؟</span>\n    </div>\n    <p class=\"quiz-desc\">اختر الإجابة الصحيحة بضغطة واحدة واكتشف النتيجة فورياً:</p>\n\n    <!-- Q1 -->\n    <div class=\"quiz-q\" id=\"q1\">\n      <div class=\"quiz-q-title\">1. ما هو نوع الشبكة التي تربط أجهزة معمل الكمبيوتر داخل المدرسة؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, true, 'إجابة عبقرية! شبكة LAN هي الشبكة المحلية التي تغطي مساحات محدودة كمدرسة أو منزل.')\">شبكة محلية (LAN)</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q1', this, false, 'إجابة غير صحيحة؛ WAN شبكة عالمية واسعة النطاق مثل الإنترنت.')\">شبكة واسعة النطاق (WAN)</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q1-fb\"></div>\n    </div>\n\n    <!-- Q2 -->\n    <div class=\"quiz-q\" id=\"q2\">\n      <div class=\"quiz-q-title\">2. هل يمكن لجهازين في المنزل تبادل الملفات والطباعة إذا انقطع اتصال الإنترنت الخارجي؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, true, 'صحيح تماماً! الشبكة المحلية LAN تعمل بشكل مستقل ومكتفٍ ذاتياً داخل المنزل حتى دون إنترنت.')\">نعم، لأن الشبكة المحلية تعمل دون حاجة لإنترنت خارجي</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q2', this, false, 'غير صحيح؛ الشبكة المحلية لا تتطلب إنترنت خارجي لتبادل الملفات بين أجهزتها.')\">لا، انقطاع الإنترنت يوقف اتصال الأجهزة ببعضها</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q2-fb\"></div>\n    </div>\n\n    <!-- Q3 -->\n    <div class=\"quiz-q\" id=\"q3\">\n      <div class=\"quiz-q-title\">3. ما وظيفة جهاز الراوتر (Router) الأساسية؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, true, 'رائع جداً! الراوتر يوجّه حزم البيانات بين شبكتك المحلية والشبكات الخارجية والإنترنت.')\">توجيه البيانات وربط الشبكة المحلية بالإنترنت</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q3', this, false, 'خطأ؛ الراوتر لا يطبع الملفات بل يوجه مسار البيانات الرقمية.')\">طباعة المستندات على الورق</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q3-fb\"></div>\n    </div>\n\n    <!-- Q4 -->\n    <div class=\"quiz-q\" id=\"q4\">\n      <div class=\"quiz-q-title\">4. هل مجرد اتصال جهازين بنفس شبكة Wi-Fi يعني بالضرورة إمكانية نقل الملفات بينهما تلقائياً؟</div>\n      <div class=\"quiz-options\">\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q4', this, true, 'إجابة ممتازة! مشاركة الملفات تتطلب تفعيل الصلاحيات والتوافق، وبعض الشبكات تعزل الأجهزة لأسباب أمنية.')\">لا، تتطلب إعدادات مشاركة خاصة وصلاحيات وصول</button>\n        <button class=\"opt-btn\" onclick=\"checkAnswer('q4', this, false, 'غير صحيح؛ الاتصال بالواي فاي لا يعني فتح الملفات تلقائياً لأسباب أمنية.')\">نعم، تفتح الملفات تلقائياً بمجرد الاتصال</button>\n      </div>\n      <div class=\"quiz-feedback\" id=\"q4-fb\"></div>\n    </div>\n  </section>\n\n  <!-- ==========================================\n       10. ARTICLE FOOTER & SIGNATURE\n       ========================================== -->\n  <footer class=\"article-footer\">\n    <div class=\"author-info\">\n      <div class=\"author-avatar\">إ</div>\n      <div class=\"author-details\">\n        <h4>م. إسلام عاطف | Eslam Atef</h4>\n        <p>مهندس برمجيات ومدرب معتمد في البرمجة والذكاء الاصطناعي للأطفال والشباب</p>\n      </div>\n    </div>\n    <div style=\"font-size: 13.5px; color: #64748b; font-weight: 700;\">\n      🚀 برمجة في دقيقة — كل ما فهمت كيف تتواصل الأجهزة، خطوت خطوة أوسع نحو فهم إنترنت الأشياء والبرمجة السحابية الحديثة.\n    </div>\n  </footer>\n\n</div>\n\n<script>\n  function checkAnswer(qId, btn, isCorrect, explanation) {\n    const parent = document.getElementById(qId);\n    const buttons = parent.querySelectorAll('.opt-btn');\n    const fb = document.getElementById(qId + '-fb');\n\n    buttons.forEach(b => {\n      b.disabled = true;\n      b.style.cursor = 'default';\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      fb.style.display = 'block';\n      fb.style.background = '#dcfce7';\n      fb.style.color = '#15803d';\n      fb.innerHTML = '✅ ' + explanation;\n    } else {\n      btn.classList.add('wrong');\n      fb.style.display = 'block';\n      fb.style.background = '#fee2e2';\n      fb.style.color = '#b91c1c';\n      fb.innerHTML = '❌ ' + explanation;\n    }\n  }\n</script>\n\n</body>\n</html>\n", "status": "منشور", "isPublished": true, "imageUrl": "https://g.top4top.io/p_3951wn90y1.png", "image": "https://g.top4top.io/p_3951wn90y1.png", "createdAt": "2026-10-25T12:00:00Z", "views": 140, "likes": 52},
  ];
}
